#!/usr/bin/env python3
"""Build a standalone, offline HTML deck from content.json (Python standard library)."""
import base64,html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
data=json.loads((ROOT/'content.json').read_text())
e=lambda s:html.escape(str(s))
def paras(s):return e(s).replace('\n','<br>')
def table(s):
 return '<table><thead><tr>'+''.join('<th>'+e(h)+'</th>' for h in s['headers'])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(c)+'</td>' for c in row)+'</tr>' for row in s['rows'])+'</tbody></table>'
def source_figure(s):
 f=s['figure'];asset=ROOT/f['asset']
 encoded=base64.b64encode(asset.read_bytes()).decode('ascii')
 url=data['sources'][f['sourceRef']]['url']
 return f'<figure class="source-figure"><div class="source-image"><img src="data:image/png;base64,{encoded}" alt="{e(f["alt"])}"></div><figcaption>Original source · <a href="{e(url)}" target="_blank" rel="noopener">{e(f["caption"])}</a></figcaption></figure>'
def source(r):
 a=data['sources'][r];return f'<a href="{e(a["url"])}" target="_blank" rel="noopener">{e(a.get("shortName",a["name"]))}</a>'
def credit():
 meta=data.get('presenter', {})
 return ' · '.join(e(meta[k]) for k in ('author','company') if meta.get(k))
def chapter(i):
 return 'CONCEPTS' if i<=3 else 'EVIDENCE' if i<=11 else 'DISCUSSION' if i<=15 else 'APPENDIX'
cover_art='<div class="cover-art" aria-label="Conceptual learning loop, illustrative"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orbit orbit-three"></div><span class="orbit-core">Retain<br><em>what helps.</em></span><span class="orbit-label label-one">01 / EXPERIENCE</span><span class="orbit-label label-two">02 / REVISE</span><span class="orbit-label label-three">03 / REUSE</span><small>CONCEPTUAL LEARNING LOOP</small></div>'
sections=[]
for i,s in enumerate(data['slides'],1):
 kind=s['kind'];refs=s['refs'];body=''
 if kind=='cover':body=f'<p class="eyebrow">{e(s["eyebrow"])}</p><h1>{e(s["title"])}</h1><p class="hero-subtitle">{e(s["subtitle"])}</p><p class="cover-line">Experience → retained change → future work</p>'
 elif kind=='closing':body=f'<p class="eyebrow">WHAT THE EVIDENCE SUPPORTS</p><h1>{e(s["title"])}</h1><p class="hero-subtitle">{paras(s["subtitle"])}</p><p class="closing-tests">{e(s["bottom"])}</p>'
 else:
  body='<header><h2>'+e(s['title'])+'</h2>'+(f'<p class="subtitle">{e(s["subtitle"])}</p>' if s.get('subtitle') else '')+'</header>'
  if kind=='section':body=f'<p class="section-kicker">{e(s["kicker"])}</p><header><h2>{e(s["title"])}</h2></header><p class="section-motivation">{e(s["body"])}</p><p class="section-preview">{e(s["preview"])}</p>'
  elif kind=='loop':body+='<div class="loop-flow">'+''.join(f'<div><span class="step-number">0{j+1}</span><strong>{e(x)}</strong></div>'+('<span class="arrow" aria-hidden="true">→</span>' if j<3 else '') for j,x in enumerate(s['steps']))+'</div><p class="takeaway">'+e(s['bottom'])+'</p>'
  elif kind=='cards':body+='<div class="ambitions">'+''.join(f'<article><span class="step-number">0{j+1}</span><h3>{e(c[0])}</h3><p>{e(c[1])}</p><strong>{e(c[2])}</strong></article>' for j,c in enumerate(s['cards']))+'</div>'
  elif kind=='source-evidence':body+=source_figure(s)+f'<div class="source-reading"><p class="metric">{e(s["callout"])}</p><div><p class="body">{e(s["body"])}</p><p class="detail">{e(s["detail"])}</p></div></div>'
  elif kind=='source-concept':body+=source_figure(s)
  elif kind=='source-story':
   body+=f'<div class="story-pair"><div><h3>{e(s["leftTitle"])}</h3><p>{paras(s["leftBody"])}</p></div><div><h3>{e(s["rightTitle"])}</h3><p>{paras(s["rightBody"])}</p></div></div>'+source_figure(s)
  elif kind=='source-guided':
   glossary='<dl class="figure-glossary">'+''.join('<div><dt>'+e(t)+'</dt><dd>'+e(p)+'</dd></div>' for t,p in s['figureGlossary'])+'</dl>' if s.get('figureGlossary') else ''
   body+='<div class="guided-layout'+(' with-glossary' if glossary else '')+'"><div>'+source_figure(s)+glossary+'</div><div class="figure-guide">'+''.join('<div><h3>'+e(t)+'</h3><p>'+e(p)+'</p></div>' for t,p in s['guide'])+'</div></div>'
  elif kind=='stream-explained':body+='<div class="table-wrap">'+table(s)+'</div>'+f'<p class="stream-summary"><strong>{e(s["callout"])}</strong> {e(s["body"])}</p><p class="adaptation-label">Stream definitions: §3.2 · Numbers calculated from Tables 2, 11–13</p>'
  elif kind=='table':body+='<div class="table-wrap">'+table(s)+'</div>'
  elif kind=='twocol':body+=f'<div class="columns"><div><h3>{e(s["leftTitle"])}</h3><p>{paras(s["leftBody"])}</p></div><div><h3>{e(s["rightTitle"])}</h3><p>{paras(s["rightBody"])}</p></div></div>'
  elif kind=='stream':body+=f'<div class="stream-metric"><p class="metric">{e(s["callout"])}</p><p>{e(s["body"])}</p></div>'+table(s)
  elif kind=='discussion':body+='<ol class="discussion-list">'+''.join(f'<li><span>{e(p[0])}</span><div><h3>{e(p[1])}</h3><p>{e(p[2])}</p></div></li>' for p in s['prompts'])+'</ol>'
  elif kind=='references':
   body+='<ul class="reference-list">'+''.join(f'<li><strong>{source(r)}</strong><span>{e(data["sources"][r]["status"])}</span><small>{e(data["sources"][r]["url"])} · {e(data["sources"][r]["locator"])}</small></li>' for r in s['referenceIds'])+'</ul>'
 if kind in ('cover','closing') and credit():body+='<p class="presenter-credit">'+credit()+'</p>'
 if kind=='cover':body+=cover_art
 if kind not in ('cover','closing'):body='<div class="running-head"><span>SELF-EVOLVING AGENTS</span><span>'+e(s.get('chapter',chapter(i)))+'</span></div>'+body
 if s.get('caveat'):body+='<p class="caveat">'+e(s['caveat'])+'</p>'
 footer=' · '.join(source(r) for r in refs) if refs else e(s.get('footer','Self-evolving agents · September 18, 2026'))
 footer += (' · '+e(s['resultLocator'])) if s.get('resultLocator') else ''
 body+=f'<footer><div>{footer}</div><span>{i:02d} / {len(data["slides"]):02d}</span></footer>'
 sections.append(f'<section id="slide-{i}" class="slide {kind}{" compact" if s.get("compact") else ""}" aria-label="Slide {i}: {e(s["title"])}" tabindex="-1">{body}</section>')
css='''
:root{--ink:#17202c;--muted:#5b6877;--accent:#2365cd;--rule:#dce2e8}*{box-sizing:border-box}html,body{margin:0;height:100%;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;color:var(--ink)}body{background:#e8ecf1}button,select{font:inherit}a{color:inherit;text-underline-offset:3px}a:hover{color:var(--accent)}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #ea9d20;outline-offset:4px}.stage{height:calc(100vh - 58px);display:flex;align-items:center;justify-content:center;overflow:hidden}.canvas{width:1280px;height:720px;flex-shrink:0;transform:scale(var(--scale,1));position:relative;transform-origin:center}.slide{display:none;background:#fff;width:1280px;height:720px;padding:43px 54px 72px;position:absolute;inset:0;overflow:hidden;border-top:5px solid var(--accent)}.slide.active{display:block}h1,h2,h3,p{margin:0}h2{font-size:43px;line-height:1.13;font-weight:650;letter-spacing:-1.5px}h3{font-size:30px;line-height:1.2;font-weight:600}.subtitle{font-size:22px;color:var(--muted);line-height:1.35;margin-top:20px}header{min-height:119px}.eyebrow{font-size:21px;letter-spacing:2px;color:var(--muted)}h1{font-size:76px;line-height:1.05;letter-spacing:-3px;font-weight:620}.cover h1{margin-top:148px}.hero-subtitle{font-size:36px;line-height:1.35;margin-top:36px;max-width:1100px}.cover-line{margin-top:64px;font-size:25px;color:var(--accent)}footer{position:absolute;left:54px;right:54px;bottom:24px;display:flex;justify-content:space-between;gap:28px;font-size:14px;color:var(--muted);line-height:1.45}footer>div{max-width:1060px}footer>span{white-space:nowrap}.caveat{position:absolute;left:54px;right:54px;bottom:68px;font-size:18px;color:var(--muted);line-height:1.3;border-top:1px solid var(--rule);padding-top:14px}.loop-flow{display:flex;align-items:center;justify-content:space-between;margin-top:73px;gap:14px}.loop-flow>div{flex:1}.step-number{display:block;color:var(--accent);font-size:20px;margin-bottom:16px}.loop-flow strong{font-size:28px;font-weight:580;white-space:nowrap}.arrow{color:var(--accent);font-size:32px;padding-top:34px}.takeaway{font-size:36px;line-height:1.3;color:var(--accent);margin-top:97px;max-width:1120px}.evidence{display:grid;grid-template-columns:650px 1fr;gap:52px;margin-top:8px}.unit{font-size:18px;color:var(--muted)}.chart svg{width:100%;height:390px;display:block}.chart small{font-size:14px;color:var(--muted)}.tick{font-size:17px;fill:var(--muted)}.value{font-size:27px;fill:var(--ink)}.category{font-size:18px;fill:var(--ink)}.interpretation{padding-top:49px}.metric{font-size:57px;line-height:1.1;color:var(--accent);letter-spacing:-1.5px}.body{font-size:28px;line-height:1.35;margin-top:25px}.detail{font-size:22px;line-height:1.4;margin-top:31px;color:var(--muted)}.table-wrap{margin-top:27px}table{border-collapse:collapse;width:100%;font-size:23px;line-height:1.22}th{text-align:left;background:#edf2f8;color:#294363;font-size:20px;font-weight:600}td,th{padding:17px 18px;border-bottom:1px solid var(--rule)}td:first-child{font-weight:580;width:27%}th:first-child{width:27%}.columns{display:grid;grid-template-columns:1fr 1fr;gap:76px;margin-top:50px}.columns h3{color:var(--accent);font-size:32px}.columns p{font-size:27px;line-height:1.5;margin-top:23px}.columns>div+div{border-left:1px solid var(--rule);padding-left:42px}.stream-metric{display:flex;gap:70px;align-items:center;margin:34px 0 27px}.stream-metric>p+ p{font-size:28px;max-width:660px}.stream table td,.stream table th{padding-top:13px;padding-bottom:13px}.discussion-list{list-style:none;padding:0;margin:33px 0 0}.discussion-list li{display:flex;gap:31px;margin-top:29px}.discussion-list li>span{font-size:28px;color:var(--accent);min-width:56px}.discussion-list h3{font-size:29px}.discussion-list p{font-size:21px;margin-top:10px;color:var(--muted)}.closing h1{font-size:60px;margin-top:83px;max-width:1120px}.closing .hero-subtitle{font-size:32px}.closing-tests{font-size:30px;color:var(--accent);margin-top:59px;white-space:pre-wrap}.reference-list ul{margin:0}.reference-list{list-style:none;padding-left:0;margin-top:15px}.reference-list li{margin:0 0 17px}.reference-list strong{font-size:20px;display:inline-block;margin-right:18px}.reference-list span{font-size:16px;color:var(--muted)}.reference-list small{display:block;font-size:14px;color:var(--muted);margin-top:5px}.toolbar{height:58px;background:#17202c;color:#fff;display:flex;align-items:center;justify-content:center;gap:12px;padding:9px 18px}.toolbar button,.toolbar select{color:#fff;border:1px solid #677382;background:transparent;border-radius:5px;padding:7px 11px;cursor:pointer;font-size:14px}.toolbar select{max-width:410px}.toolbar option{color:#17202c}.toolbar button:disabled{opacity:.35;cursor:default}.toolbar button[aria-pressed="true"]{background:#2365cd}.hint{color:#c5cdd6;font-size:13px;margin-left:12px}.notes-panel{display:none;position:fixed;right:18px;top:18px;bottom:77px;width:min(470px,90vw);background:#fff;box-shadow:0 9px 45px #0004;z-index:8;overflow:auto;padding:28px;border:1px solid var(--rule);font-size:17px;line-height:1.55}.notes-panel.open{display:block}.notes-panel h2{font-size:24px;letter-spacing:0;margin:18px 0}.notes-panel h3{font-size:18px;margin-top:22px}.notes-panel p{margin-top:15px}.notes-panel ul{padding-left:19px}.notes-close{float:right;background:none;border:0;font-size:22px;cursor:pointer}.overview .stage{height:auto;overflow:visible;display:block;padding:28px}.overview .canvas{transform:none;width:auto;height:auto;display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:22px}.overview .slide{display:block;position:relative;width:auto;height:auto;aspect-ratio:16/9;padding:22px;cursor:pointer;border:2px solid transparent;border-top:4px solid var(--accent)}.overview .slide h1,.overview .slide h2{font-size:23px;line-height:1.2;letter-spacing:-.5px;margin:0}.overview .slide> :not(header):not(h1){display:none}.overview header>*:not(h2){display:none}.overview header{min-height:0}.overview .slide.active{border:3px solid var(--accent)}.overview .toolbar{position:sticky;bottom:0}.reading .stage{display:block;height:auto;overflow:visible}.reading .canvas{width:1280px;height:auto;margin:auto;transform:none}.reading .slide{display:block;position:relative;margin:22px 0}.reading .toolbar{position:sticky;bottom:0}.status{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip:rect(0,0,0,0)}
@media(max-width:760px){.hint{display:none}.toolbar{gap:6px;padding:8px}.toolbar select{max-width:145px}.toolbar button{padding:7px}.toolbar #print{display:none}}
@media print{@page{size:1280px 720px;margin:0}html,body{height:auto;background:white}.toolbar,.notes-panel,.status{display:none!important}.stage{display:block!important;height:auto!important;overflow:visible!important;padding:0!important}.canvas{display:block!important;width:1280px!important;height:auto!important;transform:none!important;margin:0!important}.slide,.overview .slide,.reading .slide{display:block!important;position:relative!important;width:1280px!important;height:720px!important;margin:0!important;padding:43px 54px 72px!important;break-after:page;page-break-after:always;print-color-adjust:exact;-webkit-print-color-adjust:exact}.slide:last-child{break-after:auto}.overview .slide> :not(header):not(h1){display:revert}.overview .slide h1{font-size:76px}.overview .slide h2{font-size:43px}.overview header>*:not(h2){display:block}.overview header{min-height:119px}a{text-decoration:none}}
'''
css += '\n' + (ROOT/'theme.css').read_text()
js='''
const data=JSON.parse(document.querySelector('#deck-data').textContent),slides=[...document.querySelectorAll('.slide')],select=document.querySelector('#jump'),notes=document.querySelector('#notes-panel');let index=0;
slides.forEach((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=String(i+1).padStart(2,'0')+'  '+data.slides[i].title;select.append(o);s.addEventListener('click',e=>{if(document.body.classList.contains('overview')&&!e.target.closest('a')){toggleOverview(false);show(i)}})});
function renderNotes(){const s=data.slides[index];notes.innerHTML='<button class="notes-close" aria-label="Close speaker notes">×</button><h2></h2><p></p><h3>Primary sources</h3><ul></ul>';notes.querySelector('h2').textContent=(index+1)+'. '+s.title;notes.querySelector('p').textContent=s.notes;(s.refs.length?s.refs:s.referenceIds||[]).forEach(k=>{const r=data.sources[k],li=document.createElement('li'),a=document.createElement('a');a.href=r.url;a.target='_blank';a.rel='noopener';a.textContent=r.name+' — '+r.locator;li.append(a);notes.querySelector('ul').append(li)});notes.querySelector('button').onclick=()=>toggleNotes(false)}
function show(n,hash=true){index=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>{s.classList.toggle('active',i===index);s.setAttribute('aria-hidden',document.body.classList.contains('overview')||document.body.classList.contains('reading')?'false':String(i!==index))});select.value=index;document.querySelector('#prev').disabled=index===0;document.querySelector('#next').disabled=index===slides.length-1;document.querySelector('#status').textContent='Slide '+(index+1)+' of '+slides.length+': '+data.slides[index].title;if(hash)history.replaceState(null,'','#slide-'+(index+1));renderNotes()}
function resize(){document.documentElement.style.setProperty('--scale',Math.min((innerWidth-28)/1280,(innerHeight-86)/720))}
function toggleNotes(value=!notes.classList.contains('open')){notes.classList.toggle('open',value);document.querySelector('#notes').setAttribute('aria-pressed',value);if(value)notes.querySelector('button').focus();else document.querySelector('#notes').focus()}
function toggleOverview(value=!document.body.classList.contains('overview')){document.body.classList.remove('reading');document.body.classList.toggle('overview',value);document.querySelector('#overview').setAttribute('aria-pressed',value);document.querySelector('#print').setAttribute('aria-pressed','false');show(index,false)}
function fromHash(){const m=location.hash.match(/^#slide-(\\d+)$/);show(m?Number(m[1])-1:0,false)}
document.querySelector('#prev').onclick=()=>show(index-1);document.querySelector('#next').onclick=()=>show(index+1);select.onchange=()=>show(Number(select.value));document.querySelector('#notes').onclick=()=>toggleNotes();document.querySelector('#overview').onclick=()=>toggleOverview();document.querySelector('#print').onclick=()=>{document.body.classList.remove('overview');document.body.classList.toggle('reading');document.querySelector('#print').setAttribute('aria-pressed',document.body.classList.contains('reading'));document.querySelector('#overview').setAttribute('aria-pressed','false');show(index,false)};document.querySelector('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{document.querySelector('#status').textContent='Fullscreen unavailable; use the browser fullscreen command.'}};
document.addEventListener('keydown',e=>{if(e.target.closest('select,input,textarea')||e.metaKey||e.ctrlKey||e.altKey)return;if(e.key==='Escape'){toggleNotes(false);toggleOverview(false);return}if(e.target.closest('button,a')&&[' ','Enter'].includes(e.key))return;if(['ArrowRight','ArrowDown','PageDown',' '].includes(e.key)){e.preventDefault();show(index+1)}else if(['ArrowLeft','ArrowUp','PageUp'].includes(e.key)){e.preventDefault();show(index-1)}else if(e.key==='Home'){e.preventDefault();show(0)}else if(e.key==='End'){e.preventDefault();show(slides.length-1)}else if(e.key.toLowerCase()==='n')toggleNotes();else if(e.key.toLowerCase()==='o')toggleOverview()});let beforePrintMode='';window.addEventListener('beforeprint',()=>{beforePrintMode=document.body.className;document.body.classList.remove('overview','reading')});window.addEventListener('afterprint',()=>{document.body.className=beforePrintMode;resize()});window.addEventListener('resize',resize);window.addEventListener('hashchange',fromHash);resize();fromHash();
'''
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Self-evolving agents · Journal club</title><style>'+css+'</style></head><body><main class="stage" aria-label="Presentation"><div class="canvas">'+''.join(sections)+'</div></main><nav class="toolbar" aria-label="Slide controls"><button id="prev" aria-label="Previous slide">←</button><select id="jump" aria-label="Choose slide"></select><button id="next" aria-label="Next slide">→</button><button id="notes" aria-pressed="false">Notes</button><button id="overview" aria-pressed="false">Overview</button><button id="print" aria-pressed="false">All slides</button><button id="fullscreen">Fullscreen</button><span class="hint">← → navigate · N notes · O overview</span></nav><aside id="notes-panel" class="notes-panel" aria-label="Speaker notes"></aside><div id="status" class="status" role="status" aria-live="polite"></div><script type="application/json" id="deck-data">'+json.dumps(data,ensure_ascii=False).replace('</','<\\/')+'</script><script>'+js+'</script></body></html>'
(ROOT/'index.html').write_text(page)
print('Built index.html: '+str(len(sections))+' slides, offline, no dependencies')
